SLIDE6_GUIDE_PATTERN = re.compile(r'(아래 확장|최대 [0-9]+줄|아래 확장/ 최대)')
for shape in slide6.shapes:
    if shape.has_text_frame:
        assert not SLIDE6_GUIDE_PATTERN.search(shape.text_frame.text), f'Template guide text in slide6 shape {shape.shape_id}'
